struct Geo { vec2 c0, c1, d0, d1, p0, betaP, betaM, phase; };
Geo geoOf(int shape, vec2 turn) {
  Geo g = Geo(ARC_C0, ARC_C1, ARC_DIR0, ARC_DIR1, P0, BETA_P, BETA_M, PHASE);
  if (shape != 0) {
    diceState = seedOf(shape) ^ 0x2545f491u;
