  vec2 c2 = dSub(dAdd(dMul(q0, q0), dMul(q1, q1)), dMul(ARC_R0, ARC_R0));
  vec2 disc = dMax(dSub(dMul(b2, b2), dMul(dMul(dd(4.0), a2), c2)), vec2(0.0));
