// a level's rib index
vec2 kOf(Geo g, vec2 s) {
  vec2 ds = dSub(s, S0);
  vec2 b = dLess(ds, vec2(0.0)) ? g.betaM : g.betaP;
  vec2 l = dLog(dAdd(dd(1.0), dDiv(dMul(b, dAbs(ds)), g.p0)));
