// grabient kc-zpNeqM_WwiupeubyU06-8nTP_DzcBvUdAQ
// https://grabient.com/kc-zpNeqM_WwiupeubyU06-8nTP_DzcBvUdAQ?style=glass&angle=137&speed=3&fps=120&shape=999
// fluted glass: the WGSL passes its WebGPU page runs
// The page's JavaScript works out each frame's numbers as the site's player does: the ribs and their stops, the
// discs' places, the blur's taps and the uniforms below.

// ==== Pass 1: discs ==== target: the field, fw x fh texels (1/q of the filter's region), rgba8unorm, cleared to the base color, blended one, one-minus-src-alpha | inputs: the twelve discs as instanced quads (a triangle strip of 4 vertices)
// the field's size in texels, across (x) and down (y); z unused; w 1, a one the compiler cannot see
@group(0) @binding(0) var<uniform> uField: vec4f;

struct Disc {
  @builtin(position) position: vec4f,
  @location(0) @interpolate(flat) disc: vec4f,
  @location(1) @interpolate(flat) color: vec3f,
}

@vertex
fn vs_main(@location(0) corner: vec2f, @location(1) disc: vec4f, @location(2) color: vec3f) -> Disc {
  // disc: middle x, y and radius in field texels (y down), core
  let pos = disc.xy + corner * disc.z;
  var out: Disc;
  out.disc = disc;
  out.color = color;
  // WebGL's clip y turned over: its first row is a WebGPU target's top
  out.position = vec4f(pos.x / uField.x * 2.0 - 1.0, -(1.0 - pos.y / uField.y * 2.0), 0.0, 1.0);
  return out;
}

// a clip x or y the player's vertex shader gives, snapped to 16ths of a pixel
fn snap(clip: f32, size: f32) -> f32 {
  return round((0.5 * size * 16.0 - 8.0) + clip * (0.5 * size * 16.0));
}

fn plane(M0: vec3f, M1: vec3f, M2: vec3f, v: vec3f, xy: vec2f, rhw: f32) -> f32 {
  let A = v.x * M0.x + v.y * M1.x + v.z * M2.x;
  let B = v.x * M0.y + v.y * M1.y + v.z * M2.y;
  return (xy.x * A + (v.x + xy.y * B)) * rhw;
}

struct Varyings {
  local: vec2f,
  color: vec3f,
}

// a triangle set up from its corners in 16ths, the first the origin; each varying from its plane, over the
// interpolated w
fn varyings(c0: vec2f, c1: vec2f, c2: vec2f, lx: vec3f, ly: vec3f, color: vec3f, px: vec2f) -> Varyings {
  let x1 = 0.0625 * (c1.x - c0.x);
  let y1 = 0.0625 * (c1.y - c0.y);
  let x2 = 0.0625 * (c2.x - c0.x);
  let y2 = 0.0625 * (c2.y - c0.y);
  let A = 1.0 / (x1 * y2 - x2 * y1);
  let M0 = vec3f((y1 - y2) * A, (x2 - x1) * A, 1.0);
  let M1 = vec3f(y2 * A, -x2 * A, 0.0);
  let M2 = vec3f(-y1 * A, x1 * A, 0.0);
  let xy = px - c0 * 0.0625;
  let w = xy.x * (M0.x + M1.x + M2.x) + (1.0 + xy.y * (M0.y + M1.y + M2.y));
  let rhw = 1.0 / w;
  var v: Varyings;
  v.local = vec2f(plane(M0, M1, M2, lx, xy, rhw), plane(M0, M1, M2, ly, xy, rhw));
  // the color's three corners as three numbers (uField.w is 1), so no compiler factors the color out of the sums
  let k1 = color * uField.w;
  let k2 = k1 * uField.w;
  v.color = vec3f(plane(M0, M1, M2, vec3f(color.r, k1.r, k2.r), xy, rhw), plane(M0, M1, M2, vec3f(color.g, k1.g, k2.g), xy, rhw),
    plane(M0, M1, M2, vec3f(color.b, k1.b, k2.b), xy, rhw));
  return v;
}

@fragment
fn fs_main(in: Disc) -> @location(0) vec4f {
  let fw = uField.x;
  let fh = uField.y;
  let d = in.disc;
  // the quad's corners: v0 (-1, -1) and v1 (1, -1) at yA, v2 (-1, 1) and v3 (1, 1) at yB, left at xL, right at xR
  let xL = snap((d.x - d.z) / fw * 2.0 - 1.0, fw);
  let xR = snap((d.x + d.z) / fw * 2.0 - 1.0, fw);
  let yA = snap(1.0 - (d.y - d.z) / fh * 2.0, fh);
  let yB = snap(1.0 - (d.y + d.z) / fh * 2.0, fh);
  let px = floor(in.position.xy);
  let h = i32(yA - yB);
  var v: Varyings;
  if (16 * i32(px.x) * h < i32(xL) * h + i32(xR - xL) * (16 * i32(px.y) - i32(yB))) {
    v = varyings(vec2f(xL, yB), vec2f(xL, yA), vec2f(xR, yA), vec3f(-1.0, -1.0, 1.0), vec3f(1.0, -1.0, -1.0), in.color, px);
  } else {
    v = varyings(vec2f(xL, yB), vec2f(xR, yA), vec2f(xR, yB), vec3f(-1.0, 1.0, 1.0), vec3f(1.0, -1.0, 1.0), in.color, px);
  }
  let r = length(v.local);
  if (r >= 1.0) {
    discard;
  }
  let a = select((1.0 - r) / (1.0 - d.w), 1.0, r <= d.w);
  return vec4f(v.color * a, a);
}

// ==== Passes 2 and 3: blur ==== target: across into a second field texture, then down into the first, rgba8unorm, step (1 / fw, 0) then (0, 1 / fh) | inputs: the field before (linear, clamp to edge)
struct Blur {
  step: vec2f,
  taps: array<vec4f, 6>,   // offset in texels and weight, xy
}
@group(0) @binding(0) var src: texture_2d<f32>;
@group(0) @binding(1) var bilinear: sampler;
@group(0) @binding(2) var<uniform> blur: Blur;

@vertex
fn vs_main(@location(0) corner: vec2f) -> @builtin(position) vec4f {
  return vec4f(corner, 0.0, 1.0);
}

@fragment
fn fs_main(@builtin(position) frag: vec4f) -> @location(0) vec4f {
  let uv = frag.xy / vec2f(textureDimensions(src, 0));
  var c = textureSample(src, bilinear, uv).rgb * blur.taps[0].y;
  for (var i = 1; i < 6; i++) {
    let off = blur.step * blur.taps[i].x;
    c += (textureSample(src, bilinear, uv + off).rgb + textureSample(src, bilinear, uv - off).rgb) * blur.taps[i].y;
  }
  return vec4f(c, 1.0);
}

// ==== Pass 4: glass ==== target: the canvas, W x H | inputs: the rib map (textureLoad), Pass 3 (linear, clamp to edge)
struct Glass {
  origin: vec2f,   // the filter's region's corner in the design's pixels
  offset: vec2f,   // the canvas's corner in the design's pixels
  inv: vec2f,      // 1 / (q * fw), 1 / (q * fh)
  h: f32,          // the canvas's height
  scale: f32,      // the displacement's scale
}
@group(0) @binding(0) var map: texture_2d<f32>;
@group(0) @binding(1) var fieldT: texture_2d<f32>;
@group(0) @binding(2) var bilinear: sampler;
@group(0) @binding(3) var<uniform> glass: Glass;

@vertex
fn vs_main(@location(0) corner: vec2f) -> @builtin(position) vec4f {
  return vec4f(corner, 0.0, 1.0);
}

@fragment
fn fs_main(@builtin(position) frag: vec4f) -> @location(0) vec4f {
  let p = vec2i(frag.xy);
  let m = textureLoad(map, p, 0).rgb;
  let s = vec2f(p) + glass.offset + floor(glass.scale * (m.rg - 0.5) + 0.5);
  let f = (s + 0.5 - glass.origin) * glass.inv;
  let c = textureSample(fieldT, bilinear, vec2f(f.x, 1.0 - f.y)).rgb;
  return vec4f(min(vec3f(1.0), floor(c * 255.0 + 0.5) / 255.0 * (2.0 * m.b)), 1.0);
}

// ==== Bake: rib map ==== target: W x H, rgba8unorm, once for each size, angle and shape, before the frame that needs it | inputs: the ribs, a row each (a storage buffer)
struct Bake {
  origin: vec2f,                 // the canvas's corner in the design's pixels
  count: i32,                    // ribs
  stops: i32,                    // stops a rib
  line: vec4f,                   // the normal's line: x1, y1, x2 - x1, y2 - y1
  normals: array<vec4f, 17>,     // the normal's stops: offset, red, green
  shade: array<vec4f, 17>,       // the ribs' light, half the factor, at 16ths of the lens gray, x
}
// a row a rib: [cx, cy, r squared, 0], then each stop [offset, gray, 0, 0]
@group(0) @binding(0) var<storage, read> ribs: array<vec4f>;
@group(0) @binding(1) var<uniform> bake: Bake;

@vertex
fn vs_main(@location(0) corner: vec2f) -> @builtin(position) vec4f {
  return vec4f(corner, 0.0, 1.0);
}

fn stopAt(rib: i32, k: i32) -> vec2f {
  return ribs[rib * (bake.stops + 1) + 1 + k].xy;
}

@fragment
fn fs_main(@builtin(position) frag: vec4f) -> @location(0) vec4f {
  // the pixel's center in the design's pixels
  let p = frag.xy + bake.origin;
  // the smallest disc holding it, painted last, so on top: the first in the ribs' order
  var rib = -1;
  for (var k = 0; k < 256; k++) {
    if (k >= bake.count) {
      break;
    }
    let r = ribs[k * (bake.stops + 1)];
    let d = p - r.xy;
    if (dot(d, d) <= r.z) {
      rib = k;
      break;
    }
  }
  var A = 128.0;
  if (rib >= 0) {
    let r = ribs[rib * (bake.stops + 1)];
    let d = p - r.xy;
    let t = sqrt(dot(d, d) / r.z);
    let first = stopAt(rib, 0);
    let last = stopAt(rib, bake.stops - 1);
    if (t <= first.x) {
      A = first.y;
    } else if (t > last.x) {
      A = last.y;
    } else {
      var lo = 0;
      var hi = bake.stops - 1;
      for (var i = 0; i < 12; i++) {
        if (hi - lo <= 1) {
          break;
        }
        let mid = (lo + hi) / 2;
        if (t <= stopAt(rib, mid).x) {
          hi = mid;
        } else {
          lo = mid;
        }
      }
      let s0 = stopAt(rib, lo);
      let s1 = stopAt(rib, lo + 1);
      let f = select(1.0, (t - s0.x) / (s1.x - s0.x), s1.x > s0.x);
      A = s0.y + f * (s1.y - s0.y);
    }
    A = floor(A + 0.5);
  }
  let tn = clamp(dot(p - bake.line.xy, bake.line.zw) / dot(bake.line.zw, bake.line.zw), 0.0, 1.0);
  var n: vec2f;
  if (tn <= bake.normals[0].x) {
    n = bake.normals[0].yz;
  } else if (tn > bake.normals[16].x) {
    n = bake.normals[16].yz;
  } else {
    var k = 0;
    for (var i = 0; i < 16; i++) {
      if (tn > bake.normals[i + 1].x) {
        k = i + 1;
      }
    }
    let n0 = bake.normals[k];
    let n1 = bake.normals[k + 1];
    let f = select(1.0, (tn - n0.x) / (n1.x - n0.x), n1.x > n0.x);
    n = n0.yz + f * (n1.yz - n0.yz);
  }
  n = floor(n + 0.5);
  let a = A / 255.0;
  let an = n / 255.0;
  let v = clamp(2.0 * a * an - a - an + 1.0, vec2f(0.0), vec2f(1.0));
  let c = a * 16.0;
  let kk = min(15, i32(floor(c)));
  let light = bake.shade[kk].x + (c - f32(kk)) * (bake.shade[kk + 1].x - bake.shade[kk].x);
  return vec4f(floor(255.0 * v + 0.5) / 255.0, floor(255.0 * light + 0.5) / 255.0, 1.0);
}

texts.shadertoy:
// grabient kSMQbGJYI_q4CwC
// https://grabient.com/kSMQbGJYI_q4CwC?style=glass&angle=0&speed=0
// fluted glass in Shadertoy: paste each section into the tab it names and set its channels as its header says

// ==== Common ====
// The glass's colors (the site takes six along the palette; any number will do), the angle its ribs run at
// (90 as designed), its shape (0 as designed, up to 999), how fast it plays (1 as designed, 0 holds the first
// frame), frames a second at most, and the seconds it takes to ease in. A new ANGLE or SHAPE lays the ribs out again
// as it compiles; after editing the design's numbers further down, press rewind (|<< under the picture).
const int COLORS[] = int[](0x131418, 0x1c1c20, 0x27282b, 0x303134, 0x37383c, 0x3d3d41);
const int ANGLE = 0;
const int SHAPE = 0;
const float SPEED = 0.0;
const int FPS = 60;
const float EASE = 1.6;

// ---- Doubles. The site works the glass out in doubles; a pair of floats, hi + lo (about 48 bits), rounds to the same
// float, so every pass draws from the site's numbers. Each sum and product keeps its rounding error, which a compiler
// that rearranges the steps would drop ((a + b) - a is b only in exact numbers): keep() passes a float through an
// integer XOR with a 0 the compiler cannot see (ONE is iResolution.z, 1.0), so no step is moved, fused or cancelled
// across it. The RTX's driver rearranged them otherwise, the lab measured.
#define ONE iResolution.z
float keep(float x) { return uintBitsToFloat(floatBitsToUint(x) ^ (uint(ONE) - 1u)); }
vec2 twoSum(float a, float b) {
  float s = keep(a + b);
  float v = keep(s - a);
  return vec2(s, keep(keep(a - keep(s - v)) + keep(b - v)));
}
vec2 quickSum(float a, float b) {
  float s = keep(a + b);
  return vec2(s, keep(b - keep(s - a)));
}
vec2 twoProd(float a, float b) {
  float p = keep(a * b);
  float ta = keep(4097.0 * a);
  float ah = keep(ta - keep(ta - a));
  float al = keep(a - ah);
  float tb = keep(4097.0 * b);
  float bh = keep(tb - keep(tb - b));
  float bl = keep(b - bh);
  return vec2(p, keep(keep(keep(keep(ah * bh - p) + keep(ah * bl)) + keep(al * bh)) + keep(al * bl)));
}
vec2 dd(float a) { return vec2(a, 0.0); }
vec2 dAdd(vec2 a, vec2 b) {
  vec2 s = twoSum(a.x, b.x);
  vec2 t = twoSum(a.y, b.y);
  s = quickSum(s.x, s.y + t.x);
  return quickSum(s.x, s.y + t.y);
}
vec2 dSub(vec2 a, vec2 b) { return dAdd(a, -b); }
vec2 dMul(vec2 a, vec2 b) {
  vec2 p = twoProd(a.x, b.x);
  return quickSum(p.x, p.y + (a.x * b.y + a.y * b.x));
}
vec2 dDiv(vec2 a, vec2 b) {
  float q1 = keep(a.x / b.x);
  vec2 r = dSub(a, dMul(b, dd(q1)));
  float q2 = keep(r.x / b.x);
  r = dSub(r, dMul(b, dd(q2)));
  return dAdd(quickSum(q1, q2), dd(keep(r.x / b.x)));
}
vec2 dSqrt(vec2 a) {
  if (a.x <= 0.0) return vec2(0.0);
  float x = keep(sqrt(a.x));
  vec2 r = dSub(a, twoProd(x, x));
  return quickSum(x, r.x / (2.0 * x));
}
bool dLess(vec2 a, vec2 b) { return a.x < b.x || (a.x == b.x && a.y < b.y); }
vec2 dMin(vec2 a, vec2 b) { return dLess(b, a) ? b : a; }
vec2 dMax(vec2 a, vec2 b) { return dLess(a, b) ? b : a; }
vec2 dAbs(vec2 a) { return a.x < 0.0 ? -a : a; }
vec2 dFloor(vec2 a) {
  float f = floor(a.x);
  return f == a.x ? quickSum(f, floor(a.y)) : dd(f);
}
// JavaScript's Math.round: the nearest whole number, halves up
float dRound(vec2 a) { return dFloor(dAdd(a, dd(0.5))).x; }
// the site's roundings to hundredths, thousandths and ten-thousandths
vec2 r2(vec2 a) { return dDiv(dd(dRound(dMul(a, dd(100.0)))), dd(100.0)); }
vec2 r3(vec2 a) { return dDiv(dd(dRound(dMul(a, dd(1000.0)))), dd(1000.0)); }
vec2 r4(vec2 a) { return dDiv(dd(dRound(dMul(a, dd(10000.0)))), dd(10000.0)); }
const vec2 LN2 = vec2(0.6931472, -1.9046542e-9);
const vec2 PI = vec2(3.1415927, -8.742278e-8);
const vec2 HALF_PI = vec2(1.5707964, -4.371139e-8);
const vec2 EXP_C[11] = vec2[](
  vec2(1.0, 0.0), vec2(1.0, 0.0),
  vec2(0.5, 0.0), vec2(0.16666667, -4.967054e-9),
  vec2(0.041666668, -1.2417635e-9), vec2(0.008333334, -4.346172e-10),
  vec2(0.0013888889, -3.3631094e-11), vec2(0.0001984127, -2.7255969e-12),
  vec2(0.000024801588, -3.406996e-13), vec2(0.0000027557319, 3.7935712e-14),
  vec2(2.755732e-7, -7.575112e-15)
);
// e^a = 2^k (e^(r / 16))^16, r = a - k ln 2
vec2 dExp(vec2 a) {
  float k = floor(a.x / LN2.x + 0.5);
  vec2 r = dSub(a, dMul(LN2, dd(k))) * 0.0625;
  vec2 s = EXP_C[10];
  for (int i = 9; i >= 0; i--) s = dAdd(dMul(s, r), EXP_C[i]);
  for (int i = 0; i < 4; i++) s = dMul(s, s);
  return s * uintBitsToFloat(uint(int(k) + 127) << 23);
}
// Newton's steps on e^y = a from the float's own log
vec2 dLog(vec2 a) {
  vec2 y = dd(keep(log(a.x)));
  y = dAdd(y, dSub(dMul(a, dExp(-y)), dd(1.0)));
  return dAdd(y, dSub(dMul(a, dExp(-y)), dd(1.0)));
}
const vec2 SIN_C[9] = vec2[](
  vec2(1.0, 0.0), vec2(-0.16666667, 4.967054e-9),
  vec2(0.008333334, -4.346172e-10), vec2(-0.0001984127, 2.7255969e-12),
  vec2(0.0000027557319, 3.7935712e-14), vec2(-2.5052108e-8, -4.417623e-16),
  vec2(1.6059044e-10, -5.3525265e-18), vec2(-7.6471636e-13, -1.22007105e-20),
  vec2(2.8114574e-15, -1.0462085e-22)
);
const vec2 COS_C[10] = vec2[](
  vec2(1.0, 0.0), vec2(-0.5, 0.0),
  vec2(0.041666668, -1.2417635e-9), vec2(-0.0013888889, 3.3631094e-11),
  vec2(0.000024801588, -3.406996e-13), vec2(-2.755732e-7, 7.575112e-15),
  vec2(2.0876756e-9, 1.108284e-16), vec2(-1.1470745e-11, -2.3722077e-19),
  vec2(4.7794773e-14, 7.625444e-22), vec2(-1.5619207e-16, -1.5404471e-24)
);
// sine and cosine: hi and lo of each
vec4 dSinCos(vec2 a) {
  float k = floor(a.x / HALF_PI.x + 0.5);
  vec2 r = dSub(a, dMul(HALF_PI, dd(k)));
  vec2 rr = dMul(r, r);
  vec2 s = SIN_C[8];
  for (int i = 7; i >= 0; i--) s = dAdd(dMul(s, rr), SIN_C[i]);
  s = dMul(s, r);
  vec2 c = COS_C[9];
  for (int i = 8; i >= 0; i--) c = dAdd(dMul(c, rr), COS_C[i]);
  int q = int(k) & 3;
  return q == 0 ? vec4(s, c) : q == 1 ? vec4(c, -s) : q == 2 ? vec4(-s, -c) : vec4(-c, s);
}
vec2 dAtan2(vec2 y, vec2 x) {
  vec2 t = dd(atan(y.x, x.x));
  for (int i = 0; i < 2; i++) {
    vec4 sc = dSinCos(t);
    t = dAdd(t, dDiv(dSub(dMul(y, sc.zw), dMul(x, sc.xy)), dAdd(dMul(x, sc.zw), dMul(y, sc.xy))));
  }
  return t;
}
vec2 dHypot(vec2 a, vec2 b) { return dSqrt(dAdd(dMul(a, a), dMul(b, b))); }

// ---- The design: the hill climb's numbers, doubles as the site holds them.
const vec2 ARC_C0 = vec2(-0.6939, -1.0871887e-8);
const vec2 ARC_C1 = vec2(-0.6395, 2.193451e-8);
const vec2 ARC_DIR0 = vec2(0.72384, 1.7547608e-9);
const vec2 ARC_DIR1 = vec2(0.68997, -1.6479492e-8);
const vec2 ARC_R0 = vec2(0.74155, -2.8324127e-8);
const vec2 ARC_G = vec2(0.73876, 5.493164e-9);
const vec2 S0 = vec2(0.088544, -3.6654473e-9);
const vec2 P0 = vec2(0.016224, -6.0296057e-10);
const vec2 BETA_P = vec2(0.18037, -2.9850007e-9);
const vec2 BETA_M = vec2(0.13328, 5.8698655e-9);
const vec2 PHASE = vec2(6.2201, 7.400513e-8);
const vec2 LENS_A = vec2(1.8221723, 5.3234384e-8);
const vec2 LENS_B = vec2(1.3527826, 8.616488e-9);
const vec2 LENS_E = vec2(0.67391783, 1.0488618e-8);
const vec2 LENS_KAPPA = vec2(0.97, -2.8610229e-8);
const vec2 LENS_SHIFT = vec2(0.15084155, 2.0621667e-9);
const vec2 SEAM_W = vec2(13.089314, 1.872602e-7);
const vec2 DISP = vec2(0.861575, 8.8144825e-9);
const vec2 SPREAD = vec2(1.1750951, 4.194279e-8);
const vec2 JITTER = vec2(0.12508012, 7.3063102e-9);
const vec2 DISC_SIGMA = vec2(0.108252876, -2.5118345e-9);
const vec2 ORBIT_ALONG = vec2(0.19796674, -6.276286e-9);
const vec2 ORBIT_ACROSS = vec2(0.03473221, 1.5789217e-9);
const vec2 DISC_SCALE = vec2(2.3983953, 9.027689e-8);
const vec2 BLUR = vec2(28.82367, 8.372808e-7);
const vec2 REF_D = vec2(1152.56, -0.00005859375);
const vec2 SQRT2 = vec2(1.4142135, 2.4203235e-8);
const vec2 SQRT_2PI = vec2(2.5066283, -2.866023e-10);
const float CORE = 0.3626;
// the discs: how many, on a grid this many across and ROWS down, the base color among COLORS, the design's seed
const int NPTS = 12;
const int GRID_X = 4;
const int ROWS = 3;
const int BASE = 1;
const uint DESIGN_SEED = 7u;
// a lap's seconds at speed 1, and the angle the ribs run at as designed
const float LOOP = 56.0;
const int DESIGN_ANGLE = 90;
// the lens's stops across a rib, denser toward both edges
const vec2 STOP_X[29] = vec2[](
