  vec2(0.012536044, -3.234591e-10), vec2(0.028058335, -3.3923475e-10),
  vec2(0.049515568, -1.6711459e-9), vec2(0.0766379, -9.79899e-10),
  vec2(0.109084256, 2.7726188e-9), vec2(0.14644662, -6.0508087e-9),
  vec2(0.1882551, -2.3717037e-9), vec2(0.23398396, -1.9856192e-9),
  vec2(0.28305814, -6.260363e-9), vec2(0.33486047, -4.8488147e-9),
  vec2(0.38873953, 6.7500228e-9), vec2(0.44401777, -5.9578427e-9),
  vec2(0.5, -5.551115e-17), vec2(0.55598223, 5.9578427e-9),
  vec2(0.6112605, -6.7500228e-9), vec2(0.66513956, -2.4953508e-8),
  vec2(0.7169419, -2.354196e-8), vec2(0.76601607, -2.7816704e-8),
  vec2(0.8117449, -2.743062e-8), vec2(0.8535534, -2.3751515e-8),
  vec2(0.89091575, -1.02232e-8), vec2(0.9233621, 2.333164e-8),
  vec2(0.95048445, -2.0680595e-8), vec2(0.97194165, 1.5240396e-8),
  vec2(0.98746395, 4.980072e-9), vec2(0.9968561, 1.1539944e-8),
  vec2(1.0, 0.0)
