// the ribs' light, half the factor, at 16ths of the lens gray
const float SHADE[17] = float[](
  0.472, 0.4798, 0.4868, 0.4929, 0.4981, 0.5023,
  0.5057, 0.5081, 0.5097, 0.5103, 0.51, 0.5089,
