const vec2 LENS_E = vec2(0.67391783, 1.0488618e-8);
const vec2 LENS_KAPPA = vec2(0.97, -2.8610229e-8);
const vec2 LENS_SHIFT = vec2(0.15084155, 2.0621667e-9);
const vec2 SEAM_W = vec2(13.089314, 1.872602e-7);
const vec2 DISP = vec2(0.861575, 8.8144825e-9);
const vec2 SPREAD = vec2(1.1750951, 4.194279e-8);
const vec2 JITTER = vec2(0.12508012, 7.3063102e-9);
const vec2 DISC_SIGMA = vec2(0.108252876, -2.5118345e-9);
const vec2 ORBIT_ALONG = vec2(0.19796674, -6.276286e-9);
const vec2 ORBIT_ACROSS = vec2(0.03473221, 1.5789217e-9);
const vec2 DISC_SCALE = vec2(2.3983953, 9.027689e-8);
const vec2 BLUR = vec2(28.82367, 8.372808e-7);
const vec2 REF_D = vec2(1152.56, -0.00005859375);
const vec2 SQRT2 = vec2(1.4142135, 2.4203235e-8);
const vec2 SQRT_2PI = vec2(2.5066283, -2.866023e-10);
const float CORE = 0.3626;
// the discs: how many, on a grid this many across and ROWS down, the base color among COLORS, the design's seed
const int NPTS = 12;
const int GRID_X = 4;
const int ROWS = 3;
const int BASE = 1;
const uint DESIGN_SEED = 7u;
// a lap's seconds at speed 1, and the angle the ribs run at as designed
const float LOOP = 56.0;
const int DESIGN_ANGLE = 90;
// the lens's stops across a rib, denser toward both edges
const vec2 STOP_X[29] = vec2[](
  vec2(0.0, 0.0), vec2(0.003143895, 1.0158813e-10),
  vec2(0.012536044, -3.234591e-10), vec2(0.028058335, -3.3923475e-10),
  vec2(0.049515568, -1.6711459e-9), vec2(0.0766379, -9.79899e-10),
  vec2(0.109084256, 2.7726188e-9), vec2(0.14644662, -6.0508087e-9),
  vec2(0.1882551, -2.3717037e-9), vec2(0.23398396, -1.9856192e-9),
  vec2(0.28305814, -6.260363e-9), vec2(0.33486047, -4.8488147e-9),
  vec2(0.38873953, 6.7500228e-9), vec2(0.44401777, -5.9578427e-9),
  vec2(0.5, -5.551115e-17), vec2(0.55598223, 5.9578427e-9),
  vec2(0.6112605, -6.7500228e-9), vec2(0.66513956, -2.4953508e-8),
  vec2(0.7169419, -2.354196e-8), vec2(0.76601607, -2.7816704e-8),
  vec2(0.8117449, -2.743062e-8), vec2(0.8535534, -2.3751515e-8),
  vec2(0.89091575, -1.02232e-8), vec2(0.9233621, 2.333164e-8),
  vec2(0.95048445, -2.0680595e-8), vec2(0.97194165, 1.5240396e-8),
  vec2(0.98746395, 4.980072e-9), vec2(0.9968561, 1.1539944e-8),
  vec2(1.0, 0.0)
);
// the ribs' light, half the factor, at 16ths of the lens gray
const float SHADE[17] = float[](
  0.472, 0.4798, 0.4868, 0.4929, 0.4981, 0.5023,
  0.5057, 0.5081, 0.5097, 0.5103, 0.51, 0.5089,
  0.5068, 0.5038, 0.4999, 0.4951, 0.4894
