// grabient kW0B2lbAbMXISxv1E0NeJVCg
// https://grabient.com/kW0B2lbAbMXISxv1E0NeJVCg?style=glass&angle=360&speed=10&fps=1&shape=1
// fluted glass: the GLSL ES 3.00 passes its WebGL page runs
// The page's JavaScript works out each frame's numbers as the site's player does: the ribs and their stops, the
// discs' places, the blur's taps and the uniforms below.

// ==== Vertex: full target ==== the quad over a whole target, for passes 2 to 4 and the bake
#version 300 es
layout(location=0) in vec2 corner;
void main() { gl_Position = vec4(corner, 0.0, 1.0); }

// ==== Pass 1: discs ==== target: the field, fw x fh texels (1/q of the filter's region), RGBA8, cleared to the base color, blended ONE, ONE_MINUS_SRC_ALPHA | inputs: the twelve discs as instanced quads (a triangle strip of 4 vertices)
#version 300 es
layout(location=0) in vec2 corner;
layout(location=1) in vec4 disc;   // middle x, y and radius in field texels (y down), core
layout(location=2) in vec3 color;
uniform vec2 uField;
out vec2 vLocal; out vec3 vColor; flat out float vCore;
void main() {
  vec2 pos = disc.xy + corner * disc.z;
  vLocal = corner; vColor = color; vCore = disc.w;
  gl_Position = vec4(pos.x / uField.x * 2.0 - 1.0, 1.0 - pos.y / uField.y * 2.0, 0.0, 1.0);
}
#version 300 es
precision highp float;
in vec2 vLocal; in vec3 vColor; flat in float vCore;
out vec4 o;
void main() {
  float r = length(vLocal);
  if (r >= 1.0) discard;
  float a = r <= vCore ? 1.0 : (1.0 - r) / (1.0 - vCore);
  o = vec4(vColor * a, a);
}

// ==== Pass 2: blur across ==== target: a second field texture, fw x fh, RGBA8, uStep (1 / fw, 0) | inputs: Pass 1 (linear, clamp to edge)
#version 300 es
precision highp float;
uniform sampler2D uSrc;
uniform vec2 uStep;
uniform vec2 uTaps[6];
out vec4 o;
void main() {
  vec2 uv = gl_FragCoord.xy / vec2(textureSize(uSrc, 0));
  vec3 c = texture(uSrc, uv).rgb * uTaps[0].y;
  for (int i = 1; i < 6; i++) {
    vec2 off = uStep * uTaps[i].x;
    c += (texture(uSrc, uv + off).rgb + texture(uSrc, uv - off).rgb) * uTaps[i].y;
  }
  o = vec4(c, 1.0);
}

// ==== Pass 3: blur down ==== target: the first field texture, fw x fh, RGBA8, the shader of Pass 2 with uStep (0, 1 / fh) | inputs: Pass 2 (linear, clamp to edge)

// ==== Pass 4: glass ==== target: the canvas, W x H | inputs: the rib map (nearest, clamp to edge), Pass 3 (linear, clamp to edge)
#version 300 es
precision highp float;
uniform sampler2D uMap;
uniform sampler2D uFieldT;
uniform float uH;
uniform vec2 uOrigin;
uniform vec2 uOffset;
uniform vec2 uInv;
uniform float uScale;
out vec4 o;
void main() {
  ivec2 p = ivec2(gl_FragCoord.x, uH - gl_FragCoord.y);
  vec3 m = texelFetch(uMap, p, 0).rgb;
  vec2 s = vec2(p) + uOffset + floor(uScale * (m.rg - 0.5) + 0.5);
  vec2 f = (s + 0.5 - uOrigin) * uInv;
  vec3 c = texture(uFieldT, vec2(f.x, 1.0 - f.y)).rgb;
  o = vec4(min(vec3(1.0), floor(c * 255.0 + 0.5) / 255.0 * (2.0 * m.b)), 1.0);
}

// ==== Bake: rib map ==== target: W x H, RGBA8, once for each size, angle and shape, before the frame that needs it | inputs: the ribs, a row each (RGBA32F, nearest)
#version 300 es
precision highp float;
precision highp int;
uniform highp sampler2D uRibs;   // a row a rib: [cx, cy, r², 0], then each stop [offset, gray, 0, 0]
uniform int uCount;              // ribs
uniform int uStops;              // stops a rib
uniform vec2 uOrigin;            // the window's corner in the geometry's pixels
uniform vec4 uLine;              // the normal's line: x1, y1, x2 − x1, y2 − y1
uniform vec3 uNormals[17];       // the normal's stops: offset, red, green
uniform float uShade[17];        // the ribs' light, half the factor, at 16ths of the lens gray
out vec4 o;
vec2 stopAt(int rib, int k) { return texelFetch(uRibs, ivec2(1 + k, rib), 0).xy; }
void main() {
  /* the pixel's center in the geometry's pixels: a texel row is the CPU's row */
  vec2 p = gl_FragCoord.xy + uOrigin;
  /* the smallest disc holding it, painted last, so on top: the first in the ribs' order */
  int rib = -1;
  for (int k = 0; k < 256; k++) {
    if (k >= uCount) break;
    vec4 r = texelFetch(uRibs, ivec2(0, k), 0);
    vec2 d = p - r.xy;
    if (dot(d, d) <= r.z) { rib = k; break; }
  }
  float A = 128.0;
  if (rib >= 0) {
    vec4 r = texelFetch(uRibs, ivec2(0, rib), 0);
    vec2 d = p - r.xy;
    float t = sqrt(dot(d, d) / r.z);
    vec2 first = stopAt(rib, 0);
    vec2 last = stopAt(rib, uStops - 1);
    if (t <= first.x) A = first.y;
    else if (t > last.x) A = last.y;
    else {
      int lo = 0;
      int hi = uStops - 1;
      for (int i = 0; i < 12; i++) {
        if (hi - lo <= 1) break;
        int mid = (lo + hi) / 2;
        if (t <= stopAt(rib, mid).x) hi = mid; else lo = mid;
      }
      vec2 s0 = stopAt(rib, lo);
      vec2 s1 = stopAt(rib, lo + 1);
      float f = s1.x > s0.x ? (t - s0.x) / (s1.x - s0.x) : 1.0;
      A = s0.y + f * (s1.y - s0.y);
    }
    A = floor(A + 0.5);
  }
  float tn = clamp(dot(p - uLine.xy, uLine.zw) / dot(uLine.zw, uLine.zw), 0.0, 1.0);
  vec2 n;
  if (tn <= uNormals[0].x) n = uNormals[0].yz;
  else if (tn > uNormals[16].x) n = uNormals[16].yz;
  else {
    int k = 0;
    for (int i = 0; i < 16; i++) { if (tn > uNormals[i + 1].x) k = i + 1; }
    vec3 n0 = uNormals[k];
    vec3 n1 = uNormals[k + 1];
    float f = n1.x > n0.x ? (tn - n0.x) / (n1.x - n0.x) : 1.0;
    n = n0.yz + f * (n1.yz - n0.yz);
  }
  n = floor(n + 0.5);
  float a = A / 255.0;
  vec2 an = n / 255.0;
  vec2 v = clamp(2.0 * a * an - a - an + 1.0, 0.0, 1.0);
  float c = a * 16.0;
  int kk = min(15, int(floor(c)));
  float light = uShade[kk] + (c - float(kk)) * (uShade[kk + 1] - uShade[kk]);
  o = vec4(floor(255.0 * v + 0.5) / 255.0, floor(255.0 * light + 0.5) / 255.0, 1.0);
}

texts.wgsl:
// grabient kW0B2lbAbMXISxv1E0NeJVCg
// https://grabient.com/kW0B2lbAbMXISxv1E0NeJVCg?style=glass&angle=360&speed=10&fps=1&shape=1
// fluted glass: the WGSL passes its WebGPU page runs
// The page's JavaScript works out each frame's numbers as the site's player does: the ribs and their stops, the
// discs' places, the blur's taps and the uniforms below.

// ==== Pass 1: discs ==== target: the field, fw x fh texels (1/q of the filter's region), rgba8unorm, cleared to the base color, blended one, one-minus-src-alpha | inputs: the twelve discs as instanced quads (a triangle strip of 4 vertices)
// the field's size in texels, across (x) and down (y); z unused; w 1, a one the compiler cannot see
@group(0) @binding(0) var<uniform> uField: vec4f;

struct Disc {
  @builtin(position) position: vec4f,
  @location(0) @interpolate(flat) disc: vec4f,
  @location(1) @interpolate(flat) color: vec3f,
}

@vertex
fn vs_main(@location(0) corner: vec2f, @location(1) disc: vec4f, @location(2) color: vec3f) -> Disc {
  // disc: middle x, y and radius in field texels (y down), core
  let pos = disc.xy + corner * disc.z;
  var out: Disc;
  out.disc = disc;
  out.color = color;
  // WebGL's clip y turned over: its first row is a WebGPU target's top
  out.position = vec4f(pos.x / uField.x * 2.0 - 1.0, -(1.0 - pos.y / uField.y * 2.0), 0.0, 1.0);
  return out;
}

// a clip x or y the player's vertex shader gives, snapped to 16ths of a pixel
fn snap(clip: f32, size: f32) -> f32 {
  return round((0.5 * size * 16.0 - 8.0) + clip * (0.5 * size * 16.0));
}

fn plane(M0: vec3f, M1: vec3f, M2: vec3f, v: vec3f, xy: vec2f, rhw: f32) -> f32 {
  let A = v.x * M0.x + v.y * M1.x + v.z * M2.x;
  let B = v.x * M0.y + v.y * M1.y + v.z * M2.y;
  return (xy.x * A + (v.x + xy.y * B)) * rhw;
}

struct Varyings {
  local: vec2f,
  color: vec3f,
}

// a triangle set up from its corners in 16ths, the first the origin; each varying from its plane, over the
// interpolated w
fn varyings(c0: vec2f, c1: vec2f, c2: vec2f, lx: vec3f, ly: vec3f, color: vec3f, px: vec2f) -> Varyings {
  let x1 = 0.0625 * (c1.x - c0.x);
  let y1 = 0.0625 * (c1.y - c0.y);
  let x2 = 0.0625 * (c2.x - c0.x);
  let y2 = 0.0625 * (c2.y - c0.y);
  let A = 1.0 / (x1 * y2 - x2 * y1);
  let M0 = vec3f((y1 - y2) * A, (x2 - x1) * A, 1.0);
  let M1 = vec3f(y2 * A, -x2 * A, 0.0);
  let M2 = vec3f(-y1 * A, x1 * A, 0.0);
  let xy = px - c0 * 0.0625;
  let w = xy.x * (M0.x + M1.x + M2.x) + (1.0 + xy.y * (M0.y + M1.y + M2.y));
  let rhw = 1.0 / w;
  var v: Varyings;
  v.local = vec2f(plane(M0, M1, M2, lx, xy, rhw), plane(M0, M1, M2, ly, xy, rhw));
  // the color's three corners as three numbers (uField.w is 1), so no compiler factors the color out of the sums
  let k1 = color * uField.w;
  let k2 = k1 * uField.w;
  v.color = vec3f(plane(M0, M1, M2, vec3f(color.r, k1.r, k2.r), xy, rhw), plane(M0, M1, M2, vec3f(color.g, k1.g, k2.g), xy, rhw),
    plane(M0, M1, M2, vec3f(color.b, k1.b, k2.b), xy, rhw));
  return v;
}

@fragment
fn fs_main(in: Disc) -> @location(0) vec4f {
  let fw = uField.x;
  let fh = uField.y;
  let d = in.disc;
  // the quad's corners: v0 (-1, -1) and v1 (1, -1) at yA, v2 (-1, 1) and v3 (1, 1) at yB, left at xL, right at xR
  let xL = snap((d.x - d.z) / fw * 2.0 - 1.0, fw);
  let xR = snap((d.x + d.z) / fw * 2.0 - 1.0, fw);
  let yA = snap(1.0 - (d.y - d.z) / fh * 2.0, fh);
  let yB = snap(1.0 - (d.y + d.z) / fh * 2.0, fh);
  let px = floor(in.position.xy);
  let h = i32(yA - yB);
  var v: Varyings;
  if (16 * i32(px.x) * h < i32(xL) * h + i32(xR - xL) * (16 * i32(px.y) - i32(yB))) {
    v = varyings(vec2f(xL, yB), vec2f(xL, yA), vec2f(xR, yA), vec3f(-1.0, -1.0, 1.0), vec3f(1.0, -1.0, -1.0), in.color, px);
  } else {
    v = varyings(vec2f(xL, yB), vec2f(xR, yA), vec2f(xR, yB), vec3f(-1.0, 1.0, 1.0), vec3f(1.0, -1.0, 1.0), in.color, px);
  }
  let r = length(v.local);
  if (r >= 1.0) {
    discard;
  }
  let a = select((1.0 - r) / (1.0 - d.w), 1.0, r <= d.w);
  return vec4f(v.color * a, a);
}

// ==== Passes 2 and 3: blur ==== target: across into a second field texture, then down into the first, rgba8unorm, step (1 / fw, 0) then (0, 1 / fh) | inputs: the field before (linear, clamp to edge)
struct Blur {
  step: vec2f,
  taps: array<vec4f, 6>,   // offset in texels and weight, xy
}
@group(0) @binding(0) var src: texture_2d<f32>;
@group(0) @binding(1) var bilinear: sampler;
@group(0) @binding(2) var<uniform> blur: Blur;

@vertex
fn vs_main(@location(0) corner: vec2f) -> @builtin(position) vec4f {
  return vec4f(corner, 0.0, 1.0);
}

@fragment
fn fs_main(@builtin(position) frag: vec4f) -> @location(0) vec4f {
  let uv = frag.xy / vec2f(textureDimensions(src, 0));
  var c = textureSample(src, bilinear, uv).rgb * blur.taps[0].y;
  for (var i = 1; i < 6; i++) {
    let off = blur.step * blur.taps[i].x;
    c += (textureSample(src, bilinear, uv + off).rgb + textureSample(src, bilinear, uv - off).rgb) * blur.taps[i].y;
  }
  return vec4f(c, 1.0);
}

// ==== Pass 4: glass ==== target: the canvas, W x H | inputs: the rib map (textureLoad), Pass 3 (linear, clamp to edge)
struct Glass {
  origin: vec2f,   // the filter's region's corner in the design's pixels
  offset: vec2f,   // the canvas's corner in the design's pixels
  inv: vec2f,      // 1 / (q * fw), 1 / (q * fh)
  h: f32,          // the canvas's height
  scale: f32,      // the displacement's scale
}
@group(0) @binding(0) var map: texture_2d<f32>;
@group(0) @binding(1) var fieldT: texture_2d<f32>;
@group(0) @binding(2) var bilinear: sampler;
@group(0) @binding(3) var<uniform> glass: Glass;

@vertex
fn vs_main(@location(0) corner: vec2f) -> @builtin(position) vec4f {
  return vec4f(corner, 0.0, 1.0);
}

@fragment
fn fs_main(@builtin(position) frag: vec4f) -> @location(0) vec4f {
  let p = vec2i(frag.xy);
  let m = textureLoad(map, p, 0).rgb;
  let s = vec2f(p) + glass.offset + floor(glass.scale * (m.rg - 0.5) + 0.5);
  let f = (s + 0.5 - glass.origin) * glass.inv;
  let c = textureSample(fieldT, bilinear, vec2f(f.x, 1.0 - f.y)).rgb;
  return vec4f(min(vec3f(1.0), floor(c * 255.0 + 0.5) / 255.0 * (2.0 * m.b)), 1.0);
}

// ==== Bake: rib map ==== target: W x H, rgba8unorm, once for each size, angle and shape, before the frame that needs it | inputs: the ribs, a row each (a storage buffer)
struct Bake {
  origin: vec2f,                 // the canvas's corner in the design's pixels
  count: i32,                    // ribs
  stops: i32,                    // stops a rib
  line: vec4f,                   // the normal's line: x1, y1, x2 - x1, y2 - y1
  normals: array<vec4f, 17>,     // the normal's stops: offset, red, green
  shade: array<vec4f, 17>,       // the ribs' light, half the factor, at 16ths of the lens gray, x
}
// a row a rib: [cx, cy, r squared, 0], then each stop [offset, gray, 0, 0]
@group(0) @binding(0) var<storage, read> ribs: array<vec4f>;
@group(0) @binding(1) var<uniform> bake: Bake;

@vertex
fn vs_main(@location(0) corner: vec2f) -> @builtin(position) vec4f {
  return vec4f(corner, 0.0, 1.0);
}

fn stopAt(rib: i32, k: i32) -> vec2f {
  return ribs[rib * (bake.stops + 1) + 1 + k].xy;
}

@fragment
fn fs_main(@builtin(position) frag: vec4f) -> @location(0) vec4f {
  // the pixel's center in the design's pixels
  let p = frag.xy + bake.origin;
  // the smallest disc holding it, painted last, so on top: the first in the ribs' order
  var rib = -1;
  for (var k = 0; k < 256; k++) {
    if (k >= bake.count) {
      break;
    }
    let r = ribs[k * (bake.stops + 1)];
    let d = p - r.xy;
    if (dot(d, d) <= r.z) {
      rib = k;
      break;
    }
  }
  var A = 128.0;
  if (rib >= 0) {
    let r = ribs[rib * (bake.stops + 1)];
    let d = p - r.xy;
    let t = sqrt(dot(d, d) / r.z);
    let first = stopAt(rib, 0);
    let last = stopAt(rib, bake.stops - 1);
    if (t <= first.x) {
      A = first.y;
    } else if (t > last.x) {
      A = last.y;
    } else {
      var lo = 0;
      var hi = bake.stops - 1;
      for (var i = 0; i < 12; i++) {
        if (hi - lo <= 1) {
          break;
        }
        let mid = (lo + hi) / 2;
        if (t <= stopAt(rib, mid).x) {
          hi = mid;
        } else {
          lo = mid;
        }
      }
      let s0 = stopAt(rib, lo);
      let s1 = stopAt(rib, lo + 1);
      let f = select(1.0, (t - s0.x) / (s1.x - s0.x), s1.x > s0.x);
      A = s0.y + f * (s1.y - s0.y);
    }
    A = floor(A + 0.5);
  }
  let tn = clamp(dot(p - bake.line.xy, bake.line.zw) / dot(bake.line.zw, bake.line.zw), 0.0, 1.0);
  var n: vec2f;
  if (tn <= bake.normals[0].x) {
    n = bake.normals[0].yz;
  } else if (tn > bake.normals[16].x) {
    n = bake.normals[16].yz;
  } else {
    var k = 0;
    for (var i = 0; i < 16; i++) {
      if (tn > bake.normals[i + 1].x) {
        k = i + 1;
      }
    }
    let n0 = bake.normals[k];
    let n1 = bake.normals[k + 1];
    let f = select(1.0, (tn - n0.x) / (n1.x - n0.x), n1.x > n0.x);
    n = n0.yz + f * (n1.yz - n0.yz);
  }
  n = floor(n + 0.5);
  let a = A / 255.0;
  let an = n / 255.0;
  let v = clamp(2.0 * a * an - a - an + 1.0, vec2f(0.0), vec2f(1.0));
  let c = a * 16.0;
  let kk = min(15, i32(floor(c)));
  let light = bake.shade[kk].x + (c - f32(kk)) * (bake.shade[kk + 1].x - bake.shade[kk].x);
  return vec4f(floor(255.0 * v + 0.5) / 255.0, floor(255.0 * light + 0.5) / 255.0, 1.0);
}
